<template>
  <div class="space-y-4">
    <!-- Filters: one row above the cards/chart, all driving the counts. -->
    <div
      class="flex flex-wrap items-end gap-3 rounded-xl bg-white p-3 shadow-sm ring-1 ring-gray-200 dark:bg-gray-900 dark:ring-gray-800"
    >
      <div>
        <span class="mb-1.5 block text-xs text-gray-600 dark:text-gray-400">Date range</span>
        <div class="inline-flex rounded-lg bg-gray-100 p-0.5 dark:bg-gray-800" role="group" aria-label="Date range">
          <button
            v-for="opt in DATE_RANGES"
            :key="opt.value"
            type="button"
            :aria-pressed="filters.date_range === opt.value"
            class="rounded-md px-3 py-1.5 text-sm font-medium transition"
            :class="
              filters.date_range === opt.value
                ? 'bg-white text-gray-900 shadow-sm dark:bg-gray-700 dark:text-gray-100'
                : 'text-gray-600 hover:text-gray-900 dark:text-gray-400 dark:hover:text-gray-100'
            "
            @click="filters.date_range = opt.value"
          >
            {{ opt.label }}
          </button>
        </div>
      </div>
      <div class="w-full min-[480px]:w-48">
        <FormControl
          type="select"
          class="[&_[data-slot=trigger]]:w-full"
          label="Village"
          :options="villageOptions"
          v-model="filters.village"
        />
      </div>
      <div class="w-full min-[480px]:w-52">
        <FormControl
          type="select"
          class="[&_[data-slot=trigger]]:w-full"
          label="Health Worker"
          :options="healthWorkerOptions"
          v-model="filters.health_worker"
        />
      </div>
      <div class="ml-auto flex items-center gap-3">
        <span v-if="updatedAt" class="hidden text-xs text-gray-400 sm:inline">Updated {{ updatedAt }}</span>
        <Button variant="subtle" :loading="cardsLoading" @click="loadCards">
          <template #prefix>
            <LucideIcon name="refresh-cw" class="h-4 w-4" />
          </template>
          Refresh
        </Button>
      </div>
    </div>

    <ErrorMessage v-if="cardsError" :message="cardsError" />

    <div v-else class="grid gap-4 xl:grid-cols-3">
      <!-- Program cards: click opens that program's records. -->
      <div class="grid content-start gap-3 sm:grid-cols-2 xl:col-span-2">
        <template v-if="cardsLoading && !cards.length">
          <div
            v-for="i in 8"
            :key="i"
            class="flex items-center gap-4 rounded-xl bg-white p-4 ring-1 ring-gray-200 dark:bg-gray-900 dark:ring-gray-800"
          >
            <Skeleton width="2.75rem" height="2.75rem" />
            <div class="flex-1 space-y-2">
              <Skeleton width="3rem" height="1.25rem" />
              <Skeleton width="60%" height="0.75rem" />
            </div>
          </div>
        </template>
        <template v-else>
        <button
          v-for="card in cards"
          :key="card.key"
          type="button"
          class="group flex items-center gap-4 rounded-xl bg-white p-4 text-left shadow-sm ring-1 ring-gray-200 transition hover:-translate-y-0.5 hover:shadow-md hover:ring-gray-300 focus:outline-none focus-visible:ring-2 focus-visible:ring-gray-400 dark:bg-gray-900 dark:ring-gray-800 dark:hover:ring-gray-700"
          :class="{ 'opacity-60': cardsLoading }"
          @click="openDrilldown(card)"
        >
          <span
            class="flex h-11 w-11 flex-shrink-0 items-center justify-center rounded-xl"
            :class="iconClasses(card.color)"
          >
            <LucideIcon :name="card.icon || 'file-text'" class="h-5 w-5" />
          </span>
          <span class="min-w-0 flex-1">
            <span class="block text-2xl font-semibold leading-tight tabular-nums text-gray-900 dark:text-gray-100">
              {{ formatNumber(card.count) }}
            </span>
            <span class="block truncate text-sm text-gray-500 dark:text-gray-400" :title="card.label">
              {{ card.label }}
            </span>
          </span>
          <LucideIcon
            name="chevron-right"
            class="h-4 w-4 flex-shrink-0 text-gray-300 transition group-hover:translate-x-0.5 group-hover:text-gray-500 dark:text-gray-600"
          />
        </button>
        </template>
      </div>

      <!-- Records by program: a single series, so one hue (no legend - the
      title names it), sorted largest first, with values as text labels. -->
      <div class="rounded-xl bg-white p-5 shadow-sm ring-1 ring-gray-200 dark:bg-gray-900 dark:ring-gray-800">
        <div class="flex items-baseline justify-between gap-2">
          <h3 class="text-sm font-semibold text-gray-900 dark:text-gray-100">Records by program</h3>
          <span class="text-xs text-gray-500 dark:text-gray-400">{{ rangeLabel }}</span>
        </div>
        <Skeleton v-if="cardsLoading && !cards.length" width="5rem" height="2rem" class="mt-3" />
        <p v-else class="mt-3 text-3xl font-semibold tabular-nums text-gray-900 dark:text-gray-100">
          {{ formatNumber(total) }}
        </p>
        <p class="text-xs text-gray-500 dark:text-gray-400">total records</p>

        <ul class="mt-5 space-y-3">
          <li v-for="card in sortedCards" :key="card.key">
            <button
              type="button"
              class="group w-full rounded text-left focus:outline-none focus-visible:ring-2 focus-visible:ring-gray-400"
              :title="`${card.label}: ${formatNumber(card.count)}`"
              @click="openDrilldown(card)"
            >
              <span class="mb-1 flex items-center justify-between gap-2 text-xs">
                <span class="truncate text-gray-600 dark:text-gray-400">{{ card.label }}</span>
                <span class="font-medium tabular-nums text-gray-900 dark:text-gray-100">{{ formatNumber(card.count) }}</span>
              </span>
              <span class="block h-2 w-full rounded-full bg-gray-100 dark:bg-gray-800">
                <span
                  class="block h-2 rounded-full bg-blue-500 transition-all group-hover:bg-blue-600 dark:bg-blue-400 dark:group-hover:bg-blue-300"
                  :style="{ width: barWidth(card) }"
                />
              </span>
            </button>
          </li>
        </ul>
        <p v-if="!cardsLoading && cards.length && !total" class="mt-4 text-xs text-gray-400">
          No records in this range.
        </p>
      </div>
    </div>

    <!-- Drilldown: mirrors the Desk page's popup - columns and filters come
    from the card doctype's own in_list_view / in_standard_filter meta. -->
    <Dialog v-model="showDrilldown" :options="{ size: '6xl' }">
      <template #body-title>
        <div v-if="activeCard" class="flex items-center gap-3">
          <span
            class="flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-lg"
            :class="iconClasses(activeCard.color)"
          >
            <LucideIcon :name="activeCard.icon || 'file-text'" class="h-4 w-4" />
          </span>
          <h3 class="text-lg font-semibold text-gray-900 dark:text-gray-100">{{ activeCard.label }}</h3>
          <span
            v-if="!drill.loading || drill.total"
            class="rounded-full bg-gray-100 px-2 py-0.5 text-xs font-medium text-gray-600 dark:bg-gray-800 dark:text-gray-400"
          >
            {{ formatNumber(drill.total) }}
          </span>
        </div>
      </template>
      <template #body-content>
        <div class="space-y-3">
          <div
            v-if="drill.filterFields.length"
            class="flex flex-wrap items-end gap-3 rounded-lg bg-gray-50 p-3 dark:bg-gray-800/50"
          >
            <div v-for="field in drill.filterFields" :key="field.fieldname" class="w-full min-[480px]:w-44">
              <FormControl
                v-if="field.fieldtype === 'Select' || field.fieldtype === 'Link'"
                type="select"
                class="[&_[data-slot=trigger]]:w-full"
                :label="field.label"
                :options="filterOptions(field)"
                v-model="drill.filters[field.fieldname]"
              />
              <FormControl
                v-else-if="field.fieldtype === 'Date'"
                type="date"
                :label="field.label"
                v-model="drill.filters[field.fieldname]"
              />
              <FormControl
                v-else
                type="text"
                :label="field.label"
                :placeholder="`Search ${field.label}`"
                v-model="drill.filters[field.fieldname]"
              />
            </div>
            <Button v-if="hasDrillFilters" variant="ghost" @click="clearDrillFilters">
              <template #prefix>
                <LucideIcon name="x" class="h-4 w-4" />
              </template>
              Clear
            </Button>
          </div>

          <ErrorMessage v-if="drill.error" :message="drill.error" />

          <div v-else class="relative max-h-[55vh] overflow-auto rounded-lg ring-1 ring-gray-200 dark:ring-gray-800">
            <div v-if="drill.loading && !drill.records.length" class="space-y-2 p-3">
              <Skeleton v-for="i in 6" :key="i" height="2rem" />
            </div>
            <div
              v-else-if="!drill.records.length"
              class="flex flex-col items-center gap-2 py-12 text-sm text-gray-500 dark:text-gray-400"
            >
              <LucideIcon name="inbox" class="h-8 w-8 text-gray-300 dark:text-gray-600" />
              No records for this selection.
            </div>
            <table v-else class="w-full text-left text-sm" :class="{ 'opacity-60': drill.loading }">
              <thead class="sticky top-0 z-10 bg-gray-50 text-xs uppercase tracking-wide text-gray-500 dark:bg-gray-800 dark:text-gray-400">
                <tr>
                  <th v-for="col in drill.columns" :key="col.fieldname" class="whitespace-nowrap px-4 py-2.5 font-medium">
                    {{ col.fieldname === 'name' ? 'ID' : col.label }}
                  </th>
                </tr>
              </thead>
              <tbody class="divide-y divide-gray-100 dark:divide-gray-800">
                <tr
                  v-for="row in drill.records"
                  :key="row.name"
                  tabindex="0"
                  class="cursor-pointer transition hover:bg-gray-50 focus:bg-gray-50 focus:outline-none dark:hover:bg-gray-800/60 dark:focus:bg-gray-800/60"
                  @click="openRecord(row)"
                  @keydown.enter="openRecord(row)"
                >
                  <td
                    v-for="col in drill.columns"
                    :key="col.fieldname"
                    class="whitespace-nowrap px-4 py-2.5"
                    :class="
                      col.fieldname === 'name'
                        ? 'font-medium text-gray-900 dark:text-gray-100'
                        : 'text-gray-600 dark:text-gray-300'
                    "
                  >
                    <span v-if="isEmpty(row[col.fieldname])" class="text-gray-300 dark:text-gray-600">—</span>
                    <template v-else>{{ formatCell(row[col.fieldname], col) }}</template>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>

          <div class="flex flex-wrap items-center justify-between gap-3">
            <span class="text-sm text-gray-500 dark:text-gray-400">
              <template v-if="drill.total">
                Showing {{ formatNumber(drill.start + 1) }}–{{ formatNumber(drill.start + drill.records.length) }}
                of {{ formatNumber(drill.total) }}
              </template>
            </span>
            <div class="flex items-center gap-2">
              <a
                v-if="drill.total"
                :href="excelUrl"
                target="_blank"
                rel="noopener"
                class="inline-flex h-7 items-center gap-1.5 rounded px-2 text-sm font-medium text-gray-700 hover:bg-gray-100 dark:text-gray-300 dark:hover:bg-gray-800"
              >
                <LucideIcon name="download" class="h-4 w-4" />
                Excel
              </a>
              <Button :disabled="drill.loading || drill.start === 0" @click="changePage(-1)">
                <template #icon>
                  <LucideIcon name="chevron-left" class="h-4 w-4" />
                </template>
              </Button>
              <Button :disabled="drill.loading || drill.start + drill.records.length >= drill.total" @click="changePage(1)">
                <template #icon>
                  <LucideIcon name="chevron-right" class="h-4 w-4" />
                </template>
              </Button>
            </div>
          </div>
        </div>
      </template>
    </Dialog>
  </div>
</template>

<script setup>
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { Button, Dialog, ErrorMessage, FormControl, call } from 'frappe-ui'
import Skeleton from '@/components/Skeleton.vue'
import LucideIcon from '@/components/LucideIcon.vue'
import { villagesResource, healthWorkersResource, ALL_VILLAGES, ALL_HEALTH_WORKERS } from '@/data/dashboardFilters'
import { goToRecord } from '@/data/openRecord'

// Coordinator program overview - the Vue equivalent of the Desk
// chw-dashboard page, using the same backend calls. Parents must only render
// this for privileged users: every chw_dashboard_* call throws otherwise.

const router = useRouter()

const DATE_RANGES = [
  { label: 'All time', value: 'all' },
  { label: 'Today', value: 'today' },
  { label: 'This week', value: 'week' },
  { label: 'This month', value: 'month' },
]

// Same fixed page size as the Desk popup, so its Excel export (which takes
// start/page_length) matches what's on screen.
const PAGE_SIZE = 100

const ICON_CLASSES = {
  gray: 'bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-300',
  purple: 'bg-purple-100 text-purple-700 dark:bg-purple-900 dark:text-purple-200',
  blue: 'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-200',
  green: 'bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-200',
  orange: 'bg-orange-100 text-orange-700 dark:bg-orange-900 dark:text-orange-200',
  red: 'bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-200',
}

function iconClasses(color) {
  return ICON_CLASSES[color] || ICON_CLASSES.gray
}

const filters = reactive({
  date_range: 'all',
  village: ALL_VILLAGES,
  health_worker: ALL_HEALTH_WORKERS,
})

if (!villagesResource.data) villagesResource.fetch()
if (!healthWorkersResource.data) healthWorkersResource.fetch()

const villageOptions = computed(() => [
  { label: ALL_VILLAGES, value: ALL_VILLAGES },
  ...(villagesResource.data || []).map((v) => ({ label: v, value: v })),
])
const healthWorkerOptions = computed(() => [
  { label: ALL_HEALTH_WORKERS, value: ALL_HEALTH_WORKERS },
  ...(healthWorkersResource.data || []).map((v) => ({ label: v, value: v })),
])

const rangeLabel = computed(() => DATE_RANGES.find((r) => r.value === filters.date_range)?.label || '')

// ---- Cards ----
// call() with explicit args rather than useCall().fetch(args): fetch is
// useCall's execute(), which ignores any args passed to it, so filters
// would silently never reach the server. A request counter drops responses
// that arrive after a newer filter change already fired its own request.
const cards = ref([])
const cardsLoading = ref(false)
const cardsError = ref(null)
const updatedAt = ref('')
let cardsRequestId = 0

async function loadCards() {
  const requestId = ++cardsRequestId
  cardsLoading.value = true
  cardsError.value = null
  try {
    const data = await call('chw.api.get_chw_dashboard_cards', { ...filters })
    if (requestId !== cardsRequestId) return
    cards.value = data || []
    updatedAt.value = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
  } catch (e) {
    if (requestId !== cardsRequestId) return
    cardsError.value = e?.messages?.join(', ') || e?.message || 'Could not load the dashboard.'
  } finally {
    if (requestId === cardsRequestId) cardsLoading.value = false
  }
}

watch(() => [filters.date_range, filters.village, filters.health_worker], loadCards, { immediate: true })

const total = computed(() => cards.value.reduce((sum, c) => sum + (c.count || 0), 0))
const sortedCards = computed(() => [...cards.value].sort((a, b) => (b.count || 0) - (a.count || 0)))
const maxCount = computed(() => Math.max(0, ...cards.value.map((c) => c.count || 0)))

function barWidth(card) {
  if (!maxCount.value || !card.count) return '0%'
  // Floor at 2% so a small non-zero count still shows a visible sliver.
  return `${Math.max(2, (card.count / maxCount.value) * 100)}%`
}

const numberFormat = new Intl.NumberFormat()
function formatNumber(value) {
  return numberFormat.format(value || 0)
}

// ---- Drilldown ----
const showDrilldown = ref(false)
const activeCard = ref(null)
const drill = reactive({
  columns: [],
  filterFields: [],
  linkOptions: {},
  filters: {},
  records: [],
  total: 0,
  start: 0,
  loading: false,
  error: null,
})
let drillRequestId = 0
// Filters the records on screen were fetched with - lets the debounced
// filters watcher skip a change that's already been fetched for.
let fetchedFiltersKey = null

function emptyFilters(fields) {
  return Object.fromEntries(fields.map((f) => [f.fieldname, '']))
}

// Only non-empty values are sent - the backend treats {} as "no filter".
const activeDrillFilters = computed(() =>
  Object.fromEntries(Object.entries(drill.filters).filter(([, v]) => v !== '' && v != null)),
)
const hasDrillFilters = computed(() => Object.keys(activeDrillFilters.value).length > 0)

function clearDrillFilters() {
  drill.filters = emptyFilters(drill.filterFields)
}

function filterOptions(field) {
  const values =
    field.fieldtype === 'Link'
      ? drill.linkOptions[field.fieldname] || []
      : (field.options || '').split('\n').map((o) => o.trim()).filter(Boolean)
  return [{ label: 'All', value: '' }, ...values.map((v) => ({ label: v, value: v }))]
}

async function fetchDrillRecords() {
  const requestId = ++drillRequestId
  drill.loading = true
  drill.error = null
  fetchedFiltersKey = JSON.stringify(drill.filters)
  try {
    const data = await call('chw.api.chw_dashboard_drilldown', {
      card_key: activeCard.value.key,
      filters: JSON.stringify(activeDrillFilters.value),
      page_length: PAGE_SIZE,
      start: drill.start,
    })
    if (requestId !== drillRequestId) return
    drill.records = data?.records || []
    drill.total = data?.total_count || 0
  } catch (e) {
    if (requestId !== drillRequestId) return
    drill.error = e?.messages?.join(', ') || e?.message || 'Could not load records.'
  } finally {
    if (requestId === drillRequestId) drill.loading = false
  }
}

async function openDrilldown(card) {
  // Bumping the counter up front also invalidates any in-flight fetch from
  // a previously opened card, so its rows can't land in this one's table.
  const requestId = ++drillRequestId
  activeCard.value = card
  Object.assign(drill, {
    columns: [],
    filterFields: [],
    linkOptions: {},
    filters: {},
    records: [],
    total: 0,
    start: 0,
    loading: true,
    error: null,
  })
  showDrilldown.value = true

  try {
    const meta = await call('chw.api.chw_dashboard_doctype_fields', { card_key: card.key })
    if (requestId !== drillRequestId) return
    const filterFields = meta?.standard_filter_fields || []
    const linkFields = filterFields.filter((f) => f.fieldtype === 'Link' && f.options)
    const linkResults = await Promise.all(
      linkFields.map((f) =>
        call('chw.api.chw_dashboard_link_options', { link_doctype: f.options }).catch(() => []),
      ),
    )
    if (requestId !== drillRequestId) return
    drill.linkOptions = Object.fromEntries(linkFields.map((f, i) => [f.fieldname, linkResults[i] || []]))
    drill.columns = meta?.list_view_fields || []
    drill.filterFields = filterFields
    drill.filters = emptyFilters(filterFields)
  } catch (e) {
    if (requestId !== drillRequestId) return
    drill.loading = false
    drill.error = e?.messages?.join(', ') || e?.message || 'Could not load this program.'
    return
  }
  // Outside the try: fetchDrillRecords handles its own errors, and its
  // request id supersedes this one, so no further check is needed.
  fetchDrillRecords()
}

// Any filter change goes back to page 1. Debounced so typing in a text
// filter fetches once the user pauses, not per keystroke.
let filterTimer = null
watch(
  () => JSON.stringify(drill.filters),
  (key) => {
    clearTimeout(filterTimer)
    // No columns yet = openDrilldown is still loading meta (its own reset of
    // drill.filters lands here too) and will fetch on its own when done.
    if (!showDrilldown.value || !drill.columns.length || key === fetchedFiltersKey) return
    filterTimer = setTimeout(() => {
      drill.start = 0
      fetchDrillRecords()
    }, 350)
  },
)
onBeforeUnmount(() => clearTimeout(filterTimer))

// Closing invalidates whatever is still in flight.
watch(showDrilldown, (open) => {
  if (!open) {
    drillRequestId++
    clearTimeout(filterTimer)
  }
})

function changePage(direction) {
  drill.start = Math.max(0, drill.start + direction * PAGE_SIZE)
  fetchDrillRecords()
}

const excelUrl = computed(() => {
  if (!activeCard.value) return '#'
  const params = new URLSearchParams({
    card_key: activeCard.value.key,
    filters: JSON.stringify(activeDrillFilters.value),
    page_length: PAGE_SIZE,
    start: drill.start,
  })
  return `/api/method/chw.api.chw_dashboard_drilldown_excel?${params.toString()}`
})

function openRecord(row) {
  const stayedInApp = goToRecord(router, activeCard.value.doctype, row.name)
  if (stayedInApp) showDrilldown.value = false
}

function isEmpty(value) {
  return value === null || value === undefined || value === ''
}

function formatCell(value, col) {
  if (col.fieldtype === 'Date') {
    const d = new Date(`${value}T00:00:00`)
    return isNaN(d) ? value : d.toLocaleDateString(undefined, { day: '2-digit', month: 'short', year: 'numeric' })
  }
  if (col.fieldtype === 'Datetime') {
    const d = new Date(String(value).replace(' ', 'T'))
    return isNaN(d)
      ? value
      : d.toLocaleString(undefined, { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' })
  }
  if (col.fieldtype === 'Check') return value ? 'Yes' : 'No'
  return value
}
</script>
